package dev.industrialtechnology.railway;
import net.minecraft.inventory.*;import net.minecraft.item.ItemStack;
public final class InventoryTransfer {
 public static int[] slots(IInventory i,int side){if(i instanceof ISidedInventory)return ((ISidedInventory)i).getAccessibleSlotsFromSide(side);int[] a=new int[i.getSizeInventory()];for(int n=0;n<a.length;n++)a[n]=n;return a;}
 public static int insert(IInventory target,ItemStack stack,int side,int max){if(stack==null||max<=0)return 0;int total=0;for(int slot:slots(target,side)){if(slot<0||slot>=target.getSizeInventory()||!target.isItemValidForSlot(slot,stack)||target instanceof ISidedInventory&&!((ISidedInventory)target).canInsertItem(slot,stack,side))continue;ItemStack old=target.getStackInSlot(slot);if(old!=null&&(!old.isItemEqual(stack)||!ItemStack.areItemStackTagsEqual(old,stack)))continue;int capacity=Math.min(stack.getMaxStackSize(),target.getInventoryStackLimit());int n=Math.min(Math.min(max-total,stack.stackSize-total),Math.max(0,capacity-(old==null?0:old.stackSize)));if(n<=0)continue;ItemStack next=old==null?stack.copy():old.copy();next.stackSize=(old==null?0:old.stackSize)+n;target.setInventorySlotContents(slot,next);total+=n;if(total>=max||total>=stack.stackSize)break;}if(total>0)target.markDirty();return total;}
 public static int move(IInventory from,IInventory to,int fromSide,int toSide,int max){int total=0;for(int slot:slots(from,fromSide)){if(total>=max)break;if(slot<0||slot>=from.getSizeInventory())continue;ItemStack item=from.getStackInSlot(slot);if(item==null||from instanceof ISidedInventory&&!((ISidedInventory)from).canExtractItem(slot,item,fromSide))continue;int n=insert(to,item,toSide,max-total);if(n>0){from.decrStackSize(slot,n);from.markDirty();total+=n;}}return total;}
}
